# Check Cayley graph of Z/24Z with generators {5, -5, 12}
# Check for short cycles (girth < 7)

from collections import defaultdict

n = 24
generators = [5, 19, 12]  # 5, -5=19, 12

# Build adjacency
adj = defaultdict(set)
for i in range(n):
    for g in generators:
        j = (i + g) % n
        if j != i:
            adj[i].add(j)
            adj[j].add(i)

# Check degrees
for i in range(n):
    if len(adj[i]) != 3:
        print(f"Vertex {i} has degree {len(adj[i])}")

# Check girth by BFS
def find_girth(adj, n):
    min_cycle = float('inf')
    for start in range(n):
        parent = [-1] * n
        dist = [-1] * n
        queue = [start]
        dist[start] = 0
        for u in queue:
            for v in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    queue.append(v)
                elif v != parent[u]:
                    cycle_len = dist[u] + dist[v] + 1
                    if cycle_len < min_cycle:
                        min_cycle = cycle_len
                        if min_cycle < 7:
                            # Trace the cycle
                            return min_cycle, (start, u, v)
    return min_cycle, None

girth, info = find_girth(adj, n)
print(f"Girth: {girth}")
if info:
    print(f"Short cycle involving: {info}")

