generators2 = [7, 17, 12]
adj2 = defaultdict(set)
for i in range(n):
    for g in generators2:
        j = (i + g) % n
        if j != i:
            adj2[i].add(j)
            adj2[j].add(i)
girth2, info2 = find_girth(adj2, n)
print(f"Girth: {girth2}")

# Try {1, 19, 12}? No, 1 and -1=23, 19 and -19=5, 12 -> degree 5
# We need exactly 3 generators with one being self-inverse
# Self-inverse: 12 (since 2*12=24=0)
# Non-self-inverse pairs: (1,23), (5,19), (7,17), (11,13)
# But we only want one non-self-inverse pair to get degree 3

# Let me try all possibilities
print("\nTrying all generator combinations:")
for a in [1, 5, 7, 11]:
    b = (24 - a) % 24
    for c in [12]:  # only self-inverse element
        gens = [a, b, c]
        adj3 = defaultdict(set)
        for i in range(n):
            for g in gens:
                j = (i + g) % n
                if j != i:
                    adj3[i].add(j)
                    adj3[j].add(i)
        # Check all degrees are 3
        if all(len(adj3[i]) == 3 for i in range(n)):
            g3, _ = find_girth(adj3, n)
            print(f"Generators {a, b, c}: girth = {g3}")

